/// AGL name -> Unicode for Differences entries.
pub(crate) fn glyph_unicode(name: &[u8]) -> Option<&'static str> {
    GLYPH_UNICODE
        .binary_search_by(|(n, _)| n.as_bytes().cmp(name))
        .ok()
        .map(|i| GLYPH_UNICODE[i].1)
}
